exec('import csv,os,yfinance as yf\nf="virtual_portfolio.csv"; positions=list(csv.DictReader(open(f,encoding="utf-8"))) if os.path.exists(f) else []\nactive=set(x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()); rows=[r for r in csv.DictReader(open("signals_history.csv",encoding="utf-8")) if r["ticker"] in active]; latest={}\nfor r in rows:\n if r["ticker"] not in latest or r["date"]>latest[r["ticker"]]["date"]: latest[r["ticker"]]=r\ntracked={p["ticker"] for p in positions if p.get("status") in ("OPEN","PENDING")}\nfor t,r in latest.items():\n if r["signal"]=="ACHAT" and t not in tracked:\n  currency="EUR" if t.endswith((".PA",".AS")) else "USD"; positions.append({"ticker":t,"signal_date":r["date"],"signal_price":r["price"],"entry_date":"","entry_price":"","entry_type":"OUVERTURE_J","currency":currency,"eurusd_entry":"","quantity":"","invested_eur":"1000","target_price":"","stop_price":"","status":"PENDINGG","last_price":"","current_value_eur":"1000","pnl_eur":"0","pnl_pct":"0","exit_date":"","exit_price":"""exit_reason":""}); print("CANDIDAT PENDING :",t,"| Signal :",r["date"])\nfor p in positions:\n if p.get("status")!="PENDING": continue\n t=p["ticker"]; d=yf.download(t,period="1mo",progress=False,auto_adjust=True); opening=d["Open"].dropna(); opening=opening[[x.strftime("%Y-%m-%d")>p["signal_date"] for x in opening.index]]\n if len(opening)==0: print("EN ATTENTE DE L OUVERTURE :",t); continue\n entry_date=opening.index[0].strftime("%Y-%m-%d"); entry_price=float(opening.iloc[0].squeeze()); rate=float(yf.download("EURUSD=X",period="1mo",progress=False,auto_adjust=True)["Close"].dropna().iloc[-1].squeeze()); quantity=1000/entry_price if p["currency"]=="EUR" else 1000*rate/entry_price; p["entry_date"]=entry_date; p["entry_price"]=round(entry_price,4); p["eurusd_entry"]=1 if p["currency"]=="EUR" else round(rate,6); p["quantity"]=round(quantity,6); p["target_price"]=round(entry_price*1.03,4); p["stop_price"]=round(entry_price*0.98,4); p["status"]="OPEN"; p["last_price"]=round(entry_price,4); p["current_value_eur"]="1000"; p["pnl_eur"]="0"; p["pnl_pct"]="0"; print("ACHAT JOUR J :",t,"| Date :",entry_date,"| Ouverture :",round(entry_price,2),p["currency"],"| Objectif :",round(entry_price*1.03,2),"| Stop :",round(entry_price*0.98,2))\nfields=["ticker","signal_date","signal_price","entry_date","entry_price","entry_type","currency","eurusd_entry","quantity","invested_eur","target_price","stop_price","status","last_price","current_value_eur","pnl_eur","pnl_pct","exit_date","exit_price","exit_reason"]\nwith open(f,"w",newline="",encoding="utf-8") as q:\n w=csv.DictWriter(q,fieldnames=fields,extrasaction="ignore"); w.writeheader(); w.writerows(positions)\nprint("Entrees virtuelles au jour J mises a jour :",f)')
